import sys
from collections import Counter

n = int(sys.stdin.readline().strip())
s = sys.stdin.readline().strip()

c = Counter(s)
unknowns = c['?']
target_count = (n + unknowns) // 4

if (n + unknowns) % 4 != 0:
    print('===')
else:
    replacements = []
    for nucleotide in 'ACGT':
        needed = target_count - c[nucleotide]
        if needed > 0:
            replacements.extend(nucleotide * min(needed, unknowns))
            unknowns -= min(needed, unknowns)

    if len(replacements) != c['?']:
        print('===')
    else:
        result = list(s)
        j = 0
        for i in range(n):
            if result[i] == '?':
                result[i] = replacements[j]
                j += 1
        print(''.join(result))
